"use client";

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import { ArrowRight, Check, ChevronDown, Copy, Crown, Heart, Layers3, LoaderCircle, LogOut, Plus, RefreshCw, Search, Shield, Sparkles, Star, Swords, Users, X, BookOpen, PawPrint, Hexagon, Hand, CircleHelp, Skull, Wifi, WifiOff, Clock3, Bot } from "lucide-react";
import { cards, catalog, characters, typeLabels } from "../lib/catalog";
import { bidPreview, specialsFor, statsFor, type Action, type Card, type Game, type Player, type Stats } from "../lib/game";

type PublicPlayer = Omit<Player, "tokenHash" | "endPayment"> & { handCount: number; stats: Stats; endPayment?: { kind: "opponent"; ownerId: string } };
type Room = Omit<Game, "players" | "deck" | "discard" | "events" | "createdAt"> & { you: string; players: PublicPlayer[]; deckCount: number; discardCount: number; discardTop: string | null; capacityPlayers?: string[]; pendingDraw?: string | null };
type Session = { code: string; token: string };
type ServerReply = { serverNow?: number; room?: Room; version?: number; token?: string; left?: boolean; error?: string };
type Detail = { id: string; place: "catalog" | "hand" | "permanent" | "character"; owner?: string };
const SESSION_KEY = "battle-harem-session-v1";
const glyphs: Record<string, string> = { "[heart]": "♥", "[star]": "★", "[paw]": "✦", "[hand]": "♠", "[slot]": "⬡", "[hex]": "⬡", "[spade]": "♠" };
const rulesText = (text: string) => text.replace(/\[(?:heart|star|paw|hand|slot|hex|spade)\]/g, token => glyphs[token] || token);
const art = (card: Card) => `/cards/${card.id}.webp`;
const toggleIn = (list: string[], id: string) => list.includes(id) ? list.filter(x => x !== id) : [...list, id];

function Modal({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const before = document.activeElement as HTMLElement | null;
    const overflow = document.body.style.overflow; document.body.style.overflow = "hidden"; ref.current?.focus();
    const handler = (event: KeyboardEvent) => {
      if (document.querySelectorAll('[role="dialog"]').item(document.querySelectorAll('[role="dialog"]').length - 1) !== ref.current) return;
      if (event.key === "Escape") onClose();
      if (event.key === "Tab") {
        const nodes = ref.current?.querySelectorAll<HTMLElement>('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),[tabindex="0"]');
        if (!nodes?.length) return;
        const first = nodes[0]; const last = nodes[nodes.length - 1];
        if (event.shiftKey && (document.activeElement === first || document.activeElement === ref.current)) { event.preventDefault(); last.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
      }
    };
    document.addEventListener("keydown", handler);
    return () => { document.body.style.overflow = overflow; document.removeEventListener("keydown", handler); before?.focus(); };
  }, [onClose]);
  return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><div className={`modal ${wide ? "modal-wide" : ""}`} role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} ref={ref}><div className="modal-heading"><h2>{title}</h2><button className="icon-button" onClick={onClose} aria-label="Zavrieť okno"><X size={22} /></button></div>{children}</div></div>;
}
function CardTile({ id, onClick, selected, small, dead, footer, action }: { id: string; onClick: () => void; selected?: boolean; small?: boolean; dead?: boolean; footer?: ReactNode; action?: ReactNode }) {
  const card = cards[id]; if (!card) return null;
  return <div className={`card-tile ${small ? "small" : ""} ${selected ? "selected" : ""} ${dead ? "dead" : ""}`}><button className="card-art" onClick={onClick} aria-label={`Detail karty ${card.name}`}><img src={art(card)} alt={card.name} loading="lazy" />{dead && <span className="dead-label"><Skull size={13} /> Mŕtva</span>}</button><div className="card-caption"><strong title={card.name}>{card.name}</strong><span>{footer || card.subtype || typeLabels[card.type]}</span></div>{action}</div>;
}
function StatLine({ stats, compact = false }: { stats: Stats; compact?: boolean }) {
  return <div className={`stats ${compact ? "compact" : ""}`}><span title="Srdcia"><Heart className="heart" size={15} />{stats.hearts}</span><span title="Použité / dostupné hviezdy"><Star className="gold" size={15} />{stats.usedStars}/{stats.stars}</span><span title="Pasívne tames"><PawPrint size={15} />{stats.tames}</span><span title="Limit ruky"><Hand size={15} />{stats.hand}</span><span title="Obsadené / dostupné miesta"><Hexagon size={15} />{stats.usedSlots}/{stats.slots}</span></div>;
}
function Options({ value, onChange, disabled }: { value: Game["options"]; onChange: (value: Game["options"]) => void; disabled?: boolean }) {
  return <div className="options-grid"><fieldset disabled={disabled}><legend>Cieľ partie</legend><div className="segmented">{([25, 36, 50] as const).map(goal => <button type="button" className={value.goal === goal ? "active" : ""} key={goal} onClick={() => onChange({ ...value, goal })}>{goal} <Heart size={13} /></button>)}</div></fieldset><fieldset disabled={disabled}><legend>Výber postavy</legend><div className="segmented"><button type="button" className={value.selection === "random" ? "active" : ""} onClick={() => onChange({ ...value, selection: "random" })}>Náhodný</button><button type="button" className={value.selection === "choice" ? "active" : ""} onClick={() => onChange({ ...value, selection: "choice" })}>Vlastný výber</button></div></fieldset><fieldset disabled={disabled} className="timer-setting"><legend>Čas na Prihodiť / Pas</legend><select aria-label="Čas na reakciu" value={value.bidSeconds ?? 0} onChange={e => onChange({ ...value, bidSeconds: Number(e.target.value) as Game["options"]["bidSeconds"] })}><option value={30}>30 sekúnd</option><option value={60}>1 minúta</option><option value={90}>1 minúta 30 sekúnd</option><option value={120}>2 minúty</option><option value={0}>Bez limitu</option></select><p className="setting-hint">Po uplynutí času automaticky pasuješ. Každé prihodenie spustí čas odznova.</p></fieldset></div>;
}

export default function BattleHarem() {
  const [room, setRoom] = useState<Room | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [saved, setSaved] = useState<Session | null>(null);
  const [restoring, setRestoring] = useState(true);
  const [busy, setBusy] = useState(false);
  const [offline, setOffline] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [name, setName] = useState("");
  const [joinCode, setJoinCode] = useState("");
  const [entryTab, setEntryTab] = useState<"create" | "join">("create");
  const [botCount, setBotCount] = useState(0);
  const [options, setOptions] = useState<Game["options"]>({ goal: 25, selection: "random", bidSeconds: 60 });
  const [showCatalog, setShowCatalog] = useState(false);
  const [showRules, setShowRules] = useState(false);
  const [showCharacters, setShowCharacters] = useState(false);
  const [detail, setDetail] = useState<Detail | null>(null);
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState("all");
  const [replace, setReplace] = useState<string[]>([]);
  const [composer, setComposer] = useState<string | null>(null);
  const [bidCards, setBidCards] = useState<string[]>([]);
  const [reserveOpponent, setReserveOpponent] = useState("");
  const [showEnd, setShowEnd] = useState(false);
  const [discards, setDiscards] = useState<string[]>([]);
  const [endSpecial, setEndSpecial] = useState("regular");
  const [endTarget, setEndTarget] = useState("");
  const [clockTick, setClockTick] = useState(0);
  const serverClock = useRef({ server: 0, local: 0 });
  const versionRef = useRef(-1);
  const busyRef = useRef(false);
  const sessionRef = useRef<Session | null>(null);
  const me = room?.players.find(p => p.id === room.you);
  const current = room?.players[room.turn];
  const myTurn = !!room && current?.id === room.you;
  const capacitiesBlocked = !!room?.capacityPlayers?.length;
  const canAct = room?.phase === "playing" && myTurn && !room.auction && !busy && !capacitiesBlocked;
  const mySpecials = me ? specialsFor(me as unknown as Player, cards) : [];
  const overflow = !!me && (me.stats.usedStars > me.stats.stars || me.stats.usedSlots > me.stats.slots);
  const canDeploy = room?.phase === "playing" && myTurn && !room.auction && !busy && (!capacitiesBlocked || overflow);
  const deadline = room?.auction?.deadlineAt;
  const remaining = deadline ? Math.max(0, Math.ceil((deadline - (serverClock.current.server + clockTick - serverClock.current.local)) / 1000)) : null;
  const expired = remaining === 0;
  const timerLabel = remaining === null ? "Bez časového limitu" : expired ? "Čas vypršal · vyhodnocujem…" : `${Math.floor(remaining / 60)}:${String(remaining % 60).padStart(2, "0")} na reakciu`;
  const timerDisplay = <div className={`auction-timer ${remaining !== null && remaining <= 10 ? "urgent" : ""}`}><Clock3 size={17} /><strong>{timerLabel}</strong><span>{remaining !== null ? "Potom automaticky Pas" : "Reaguj tlačidlom Prihodiť alebo Pas"}</span></div>;
  const canClean = room?.phase === "playing" && !busy && (overflow || canAct);
  const closeDetail = useCallback(() => setDetail(null), []);
  const closeCatalog = useCallback(() => setShowCatalog(false), []);
  const closeRules = useCallback(() => setShowRules(false), []);
  const closeCharacters = useCallback(() => setShowCharacters(false), []);
  const closeComposer = useCallback(() => setComposer(null), []);
  const closeEnd = useCallback(() => setShowEnd(false), []);
  const accept = useCallback((data: ServerReply, expected?: string) => {
    if (expected && sessionRef.current?.code !== expected) return;
    if (data.room && (data.version ?? 0) >= versionRef.current) {
      versionRef.current = data.version ?? 0; setRoom(data.room); setOffline(false);
      if (data.serverNow) { const local = performance.now(); serverClock.current = { server: data.serverNow, local }; setClockTick(local); }
      const own = data.room.players.find(p => p.id === data.room!.you);
      if (own) {
        const owned = new Set([...own.hand, ...own.table.map(p => p.id)]);
        setBidCards(ids => ids.filter(id => owned.has(id)));
        setDiscards(ids => ids.filter(id => own.hand.includes(id)));
        setReplace(ids => ids.filter(id => [...own.table, ...own.harem].some(p => p.id === id)));
      }
    }
  }, []);
  const fetchRoom = useCallback(async (active: Session, initial = false) => {
    try {
      const response = await fetch(`/api/room?code=${encodeURIComponent(active.code)}`, { headers: { "X-Player-Token": active.token }, cache: "no-store" });
      const data = await response.json() as ServerReply;
      if (!response.ok) throw new Error(data.error || "Miestnosť sa nepodarilo načítať.");
      accept(data, active.code); if (initial) setError("");
    } catch (e) {
      if (sessionRef.current?.code !== active.code) return;
      setOffline(true);
      if (initial) { setError(e instanceof Error ? e.message : "Obnovenie spojenia sa nepodarilo."); setSession(null); sessionRef.current = null; }
    } finally { if (initial) setRestoring(false); }
  }, [accept]);
  useEffect(() => {
    const invite = new URLSearchParams(window.location.search).get("room");
    if (invite) { setJoinCode(invite.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 6)); setEntryTab("join"); }
    try {
      const value = JSON.parse(localStorage.getItem(SESSION_KEY) || "null") as Session | null;
      if (value?.code && value?.token) { setSaved(value); setSession(value); sessionRef.current = value; void fetchRoom(value, true); }
      else setRestoring(false);
      setName(localStorage.getItem("battle-harem-name") || "");
    } catch { setRestoring(false); }
  }, [fetchRoom]);
  useEffect(() => {
    if (!session) return;
    const timer = window.setInterval(() => { if (!busyRef.current && document.visibilityState === "visible") void fetchRoom(session); }, 1600);
    const update = () => { if (!busyRef.current) void fetchRoom(session); };
    window.addEventListener("focus", update); window.addEventListener("online", update);
    return () => { clearInterval(timer); window.removeEventListener("focus", update); window.removeEventListener("online", update); };
  }, [session, fetchRoom]);
  useEffect(() => {
    if (!deadline) return;
    setClockTick(performance.now());
    const tick = window.setInterval(() => setClockTick(performance.now()), 250);
    return () => clearInterval(tick);
  }, [deadline]);
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(""), 3500); return () => clearTimeout(timer); }, [notice]);
  useEffect(() => {
    if (composer === "bid" && !room?.auction) { setComposer(null); setBidCards([]); }
    if (room?.phase === "finished") { setComposer(null); setShowEnd(false); setDetail(null); }
  }, [room?.auction, room?.phase, composer]);
  async function request(body: Record<string, unknown>, secret?: string) {
    if (busyRef.current) return false;
    setBusy(true); busyRef.current = true; setError("");
    try {
      const response = await fetch("/api/room", { method: "POST", headers: { "Content-Type": "application/json", ...(secret ? { "X-Player-Token": secret } : {}) }, body: JSON.stringify(body) });
      const data = await response.json() as ServerReply;
      if (!response.ok) throw new Error(data.error || "Akcia sa nepodarila. Skús to znova.");
      if (data.token && data.room) {
        const next = { code: data.room.code, token: data.token };
        versionRef.current = -1; sessionRef.current = next; setSession(next); setSaved(next);
        localStorage.setItem(SESSION_KEY, JSON.stringify(next)); localStorage.setItem("battle-harem-name", name.trim());
      }
      if (data.left) { setRoom(null); setSession(null); setSaved(null); sessionRef.current = null; versionRef.current = -1; localStorage.removeItem(SESSION_KEY); }
      else accept(data);
      return true;
    } catch (e) { setError(e instanceof Error ? e.message : "Spojenie sa nepodarilo."); return false; }
    finally { setBusy(false); busyRef.current = false; }
  }
  async function act(action: Action) { if (!session || busyRef.current) return false; return request({ op: "action", code: session.code, actionId: crypto.randomUUID(), action }, session.token); }
  function openDetail(id: string, place: Detail["place"] = "catalog", owner?: string) { setReplace([]); setDetail({ id, place, owner }); }
  function startComposer(id: string) { setBidCards([]); setReserveOpponent(""); setComposer(id); setDetail(null); }
  async function copyInvite() {
    if (!room) return;
    const url = new URL(window.location.href); url.search = ""; url.hash = ""; url.searchParams.set("room", room.code);
    try { await navigator.clipboard.writeText(url.toString()); setNotice("Pozvánka je skopírovaná. Pošli ju kamarátom."); }
    catch { setNotice(`Kód miestnosti: ${room.code}`); }
  }
  function disconnect() { setRoom(null); setSession(null); sessionRef.current = null; versionRef.current = -1; setDetail(null); setComposer(null); setShowEnd(false); }
  async function submitBid() {
    const target = composer === "bid" ? room?.auction?.targetId : composer; if (!target) return;
    const action: Action = composer === "bid" ? { type: "bid", cards: bidCards } : { type: "summon", cardId: target, cards: bidCards, ...(reserveOpponent ? { reserveOpponentId: reserveOpponent } : {}) };
    if (await act(action)) { setComposer(null); setBidCards([]); }
  }
  async function endTurn() {
    const action: Action = { type: "endTurn", cards: discards };
    if (endSpecial === "dead") { action.special = "dead"; action.targetId = endTarget; }
    if (await act(action)) { setShowEnd(false); setDiscards([]); }
  }
  const detailCard = detail ? cards[detail.id] : null;
  let deploymentStats: Stats | null = null;
  if (detail?.place === "hand" && detailCard && me && room && ["ability", "charge", "harem"].includes(detailCard.type)) {
    const projection = structuredClone(room) as unknown as Game;
    const own = projection.players.find(p => p.id === me.id)!;
    own.harem = own.harem.filter(p => !replace.includes(p.id));
    own.table = own.table.filter(p => !replace.includes(p.id));
    own.table.push({ id: detailCard.id, ...(detailCard.type === "charge" ? { readyAt: own.turns + 1 } : {}) });
    deploymentStats = statsFor(projection, me.id, cards);
  }
  const deploymentFits = !deploymentStats || (deploymentStats.usedStars <= deploymentStats.stars && deploymentStats.usedSlots <= deploymentStats.slots);
  const selectedPermanent = detail?.place === "permanent" && detail.owner === me?.id ? [...(me?.harem || []), ...(me?.table || [])].find(x => x.id === detail.id) : null;
  const targetId = composer === "bid" ? room?.auction?.targetId : composer;
  const targetCard = targetId ? cards[targetId] : null;
  let preview = 0;
  if (room && me && targetId) { try { preview = bidPreview(room as unknown as Game, me.id, targetId, bidCards, cards); } catch { /* Server validates the authoritative state. */ } }
  const threshold = composer === "bid" && room?.auction ? room.auction.bids[room.auction.leaderId].power + 1 : targetCard?.cost.tames || 0;
  const candidateIds = me ? [...me.hand.filter(id => cards[id].type === "tame"), ...me.table.filter(x => cards[x.id].type === "charge" && (x.readyAt || 0) <= me.turns).map(x => x.id)] : [];
  const myAuctionLeader = room?.auction?.leaderId === me?.id;
  const alreadyPassed = !!room?.auction?.passes.includes(me?.id || "");
  const catalogueCards = catalog.filter(c => (filter === "all" || c.type === filter) && `${c.name} ${c.subtype || ""} ${c.effectText}`.toLowerCase().includes(query.toLowerCase()));
  const canStart = !!room && room.players.length >= 2 && room.players.every(p => p.ready);

  return <div className="app-shell">
    <header className="site-header"><a className="brand" href="/" onClick={e => { if (room) { e.preventDefault(); setShowRules(true); } }} aria-label="Battle Harem"><span className="brand-mark"><Swords size={22} /></span><span>BATTLE <b>HAREM</b><small>BOJUJ O SVOJU WAIFU</small></span></a><nav aria-label="Hlavná navigácia"><button onClick={() => setShowCatalog(true)}><Layers3 size={17} /><span>Karty</span></button><button onClick={() => setShowRules(true)}><BookOpen size={17} /><span>Ako hrať</span></button>{!room && <a className="nav-play" href="#play">Bojuj teraz <ArrowRight size={14} /></a>}{room && <span className={`connection ${offline ? "offline" : ""}`}>{offline ? <WifiOff size={14} /> : <Wifi size={14} />}<span>{offline ? "Obnovujem spojenie" : "Online"}</span></span>}</nav></header>
    {error && <div className="error-banner" role="alert"><CircleHelp size={19} /><span>{error}</span><button onClick={() => setError("")} aria-label="Zavrieť chybovú správu"><X size={17} /></button></div>}
    {notice && <div className="toast" role="status"><Check size={17} />{notice}</div>}
    {restoring ? <main className="loading-screen"><LoaderCircle className="spin" size={34} /><h2>Vraciame ťa k stolu…</h2><p>Obnovuje sa tvoja uložená partia.</p></main> : !room ? <main className="landing">
      <section className="hero"><div className="hero-copy"><p className="eyebrow"><span /> KARTOVÁ HRA PRE 2–8 HRÁČOV</p><h1>Tvoj hárem.<br /><em>Tvoja stratégia.</em></h1><p className="hero-description">Zostav svoj tím. Objav silné kombinácie.<br />A získaj si srdcia skôr než tvoji súperi.</p><div className="hero-tags"><span><Swords size={15} /> Súboje o každú kartu</span><span><Users size={15} /> S kamarátmi aj počítačom</span></div><a className="text-link" href="#play">Sadni si k hernému stolu <ArrowRight size={18} /></a></div><div className="hero-art" aria-label="Ukážka kariet Battle Harem"><div className="orbit orbit-one" /><div className="orbit orbit-two" /><div className="hero-card back"><img src="/cards/p16-r1-c5.webp" alt="Postava Yamada Hiroto" /></div><div className="hero-card side"><img src="/cards/p05-r2-c3.webp" alt="Karta Tanaka Michi" /></div><div className="hero-card front"><img src="/cards/p01-r2-c6.webp" alt="Karta Amagiri Arisu" /></div><div className="floating-token"><Heart fill="currentColor" size={19} /><span>Každá kombinácia sa počíta.</span></div><span className="art-spark spark-one">✦</span><span className="art-spark spark-two">✧</span></div></section>
      <section className="showcase" aria-label="Ukážka kolekcie"><div className="showcase-heading"><span><Sparkles size={15} /> MALÝ VÝBER. VEĽKÉ MOŽNOSTI.</span><button onClick={() => setShowCatalog(true)}>Všetky karty <ArrowRight size={15} /></button></div><div className="showcase-track">{["Yamada Hiroto", "Amashiro Remi", "Myselphie", "Amagiri Arisu", "Tanaka Michi", "Atsu Keiko", "Fumetsu Kowa", "Sunny Day"].map(name => catalog.find(c => c.name === name)).filter((c): c is Card => !!c).map(card => <button key={card.id} onClick={() => openDetail(card.id)} aria-label={`Pozrieť kartu ${card.name}`}><img src={art(card)} alt={card.name} loading="lazy" /></button>)}</div><div className="showcase-dots" aria-hidden="true"><i /><i /><i /></div></section>
      <section className="play-section" id="play"><div className="play-intro"><p className="eyebrow">TVOJA ĎALŠIA PARTIA</p><h2>Pridaj sa do boja.</h2><p>Pozvi kamarátov alebo vyzvi počítačových súperov. Hraj priamo v prehliadači, aj keď si práve sám.</p><div className="game-facts"><span><b>299</b>kariet v kolekcii</span><span><b>25</b>jedinečných postáv</span><span><b>2–8</b>hráčov pri stole</span></div></div><div className="entry-card"><div className="entry-tabs"><button className={entryTab === "create" ? "active" : ""} onClick={() => setEntryTab("create")}>Vytvoriť miestnosť</button><button className={entryTab === "join" ? "active" : ""} onClick={() => setEntryTab("join")}>Pripojiť sa</button></div><form onSubmit={e => { e.preventDefault(); void request(entryTab === "create" ? { op: "create", name: name.trim(), options, botCount } : { op: "join", name: name.trim(), code: joinCode.toUpperCase() }); }}><label className="field-label" htmlFor="nickname">Tvoja prezývka</label><input id="nickname" value={name} onChange={e => setName(e.target.value)} placeholder="Ako ťa majú volať súperi?" maxLength={24} minLength={1} required autoComplete="nickname" />{entryTab === "create" ? <><Options value={options} onChange={setOptions} disabled={busy} /><div className="bot-setting"><label className="field-label" htmlFor="bot-count"><Bot size={16} />Počítačoví súperi</label><select id="bot-count" value={botCount} disabled={busy} onChange={e => setBotCount(Number(e.target.value))}><option value={0}>Bez počítačov · pozvem kamarátov</option>{[1, 2, 3, 4, 5, 6, 7].map(n => <option value={n} key={n}>{n === 1 ? "1 počítač · hra vo dvojici" : `${n} ${n < 5 ? "počítače" : "počítačov"}`}</option>)}</select><p className="setting-hint">Pre hru osamote vyber aspoň jedného. V čakárni ich môžeš pridať alebo odobrať.</p></div></> : <><label className="field-label" htmlFor="room-code">Kód miestnosti</label><input id="room-code" className="code-input" value={joinCode} onChange={e => setJoinCode(e.target.value.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 6))} placeholder="ABC234" minLength={6} maxLength={6} required autoComplete="off" /></>}<button className="button primary full" disabled={busy || !name.trim() || (entryTab === "join" && joinCode.length !== 6)}>{busy ? <LoaderCircle className="spin" size={18} /> : entryTab === "create" ? <Plus size={18} /> : <ArrowRight size={18} />}{entryTab === "create" ? botCount ? "Hrať proti počítaču" : "Vytvoriť herný stôl" : "Pripojiť sa k hre"}</button><p className="entry-note"><Shield size={13} /> Bez registrácie. Stačí prezývka a pozvánka.</p></form>{saved && <button className="resume-button" disabled={busy} onClick={() => { versionRef.current = -1; setSession(saved); sessionRef.current = saved; setRestoring(true); void fetchRoom(saved, true); }}><RefreshCw size={15} />Obnoviť miestnosť {saved.code}</button>}</div></section>
      <section className="how-strip"><div><span>01</span><h3>Vyber si postavu</h3><p>Každý hrdina má svoje silné stránky.</p></div><div><span>02</span><h3>Prebi súperov</h3><p>Prihoď tames a získaj kartu pre seba.</p></div><div><span>03</span><h3>Poskladaj víťazstvo</h3><p>Prepoj bonusy a dosiahni cieľ sŕdc.</p></div></section><footer className="site-footer"><span>Battle Harem <span className="muted">·</span> Fight for your waifus</span><button onClick={() => setShowRules(true)}>Pravidlá hry <ArrowRight size={14} /></button></footer>
    </main> : room.phase === "lobby" ? <main className="room-page lobby-page"><div className="page-heading"><div><p className="eyebrow">ČAKÁREŇ</p><h1>Za chvíľu rozdávame.</h1><p>Pozvi kamarátov alebo pridaj počítač. Potvrď pripravenosť a začnite hrať.</p></div><div className="room-code-box"><span>KÓD MIESTNOSTI</span><button onClick={copyInvite} title="Skopírovať pozvánku">{room.code}<Copy size={19} /></button></div></div><div className="lobby-layout"><section className="surface lobby-players"><div className="section-heading"><h2>Hráči pri stole <span>{room.players.length}/8</span></h2><button className="button secondary small-button" onClick={copyInvite}><Plus size={15} />Pozvať</button></div><div className="bot-lobby-controls"><span><Bot size={18} />Počítač hrá samostatne a nevidí tvoje karty.</span>{room.hostId === room.you && <button className="button secondary small-button" disabled={busy || room.players.length >= 8} onClick={() => void act({ type: "addBot" })}><Plus size={15} />Pridať počítač</button>}</div><div className="player-list">{room.players.map((player, i) => <div className="lobby-player" key={player.id}><div className="player-avatar">{player.characterId ? <img src={art(cards[player.characterId])} alt={cards[player.characterId].name} /> : <span>{String(i + 1).padStart(2, "0")}</span>}</div><div><strong>{player.name}{player.bot && <Bot size={14} aria-label="Počítačový súper" />}{player.id === room.you && <small>TY</small>}{player.id === room.hostId && <Crown size={14} className="gold" />}</strong><p>{room.options.selection === "random" ? "Postava sa vyžrebuje pri štarte" : player.characterId ? cards[player.characterId].name : "Vyberá si postavu"}</p></div><span className={`readiness ${player.ready ? "ready" : ""}`}>{player.ready ? <Check size={15} /> : <span className="waiting-dot" />}{player.ready ? "Pripravený" : "Čaká"}</span>{player.bot && room.hostId === room.you && <button className="icon-button remove-bot" disabled={busy} aria-label={`Odobrať ${player.name}`} title="Odobrať počítač" onClick={() => void act({ type: "removeBot", playerId: player.id })}><X size={17} /></button>}</div>)}{room.players.length < 2 && <div className="empty-player"><Users size={23} /><span>Pridaj počítač alebo pozvi kamaráta</span></div>}</div><div className="lobby-actions"><button className={`button ${me?.ready ? "secondary" : "primary"}`} disabled={busy || (room.options.selection === "choice" && !me?.characterId)} onClick={() => void act({ type: "ready" })}>{me?.ready ? <Check size={18} /> : <Shield size={18} />}{me?.ready ? "Pripravený · zmeniť" : "Som pripravený"}</button>{room.hostId === room.you && <button className="button gold-button" disabled={busy || !canStart} onClick={() => void act({ type: "start" })}><Swords size={18} />Začať partiu</button>}</div><p className="muted small-text">{room.players.length < 2 ? "Stačí ty a jeden počítač. Pri stole môže byť spolu 2 až 8 hráčov." : !canStart ? "Hra sa začne, keď všetci potvrdia pripravenosť a hostiteľ spustí partiu." : "Všetci sú pripravení. Hostiteľ môže začať."}</p></section><aside className="lobby-aside"><section className="surface"><p className="eyebrow">NASTAVENIA PARTIE</p><Options value={room.options} disabled={room.hostId !== room.you || busy} onChange={value => void act({ type: "options", options: value })} /><p className="muted small-text">{room.hostId === room.you ? "Po zmene nastavení ľudia znova potvrdia pripravenosť. Počítače sú pripravené automaticky." : "Nastavenia vyberá hostiteľ miestnosti."}</p></section><section className="surface character-choice"><p className="eyebrow">TVOJA POSTAVA</p>{room.options.selection === "random" ? <div className="random-character"><Sparkles size={35} /><h3>Nech rozhodne osud.</h3><p>Náhodnú postavu dostaneš pri rozdaní kariet.</p></div> : <>{me?.characterId ? <div className="selected-character"><img src={art(cards[me.characterId])} alt={cards[me.characterId].name} /><div><h3>{cards[me.characterId].name}</h3><p>{rulesText(cards[me.characterId].effectText)}</p></div></div> : <p className="muted">Vyber si jednu z 25 postáv a postav na jej schopnostiach svoju stratégiu.</p>}<button className="button secondary full" onClick={() => setShowCharacters(true)}>Vybrať postavu<ChevronDown size={16} /></button></>}</section></aside></div><button className="text-button muted" disabled={busy} onClick={() => void act({ type: "leave" })}><LogOut size={16} />Opustiť čakáreň</button></main> : <main className="room-page game-page">
      <div className="game-topline"><div><span className="eyebrow">MIESTNOSŤ {room.code}</span><span className="turn-chip">Ťah {room.turnNumber}</span></div><div className="table-meta"><span><Heart size={15} />Cieľ {room.options.goal}</span><span><Layers3 size={15} />Balíček {room.deckCount}</span><span>Odhodené {room.discardCount}</span><button className="icon-button" onClick={disconnect} title="Odpojiť sa; partia sa uloží" aria-label="Odpojiť sa od stola"><LogOut size={17} /></button></div></div>
      {room.phase === "finished" && <section className="victory-banner"><div className="winner-crown"><Crown size={36} /></div><div><p className="eyebrow">PARTIA JE ROZHODNUTÁ</p><h1>{room.winnerId === room.you ? "Víťazstvo je tvoje!" : `${room.players.find(p => p.id === room.winnerId)?.name} vyhráva!`}</h1><p>Cieľ {room.options.goal} sŕdc dosiahnutý. Dobrá kombinácia, dobrá partia.</p></div>{room.hostId === room.you ? <button className="button gold-button" disabled={busy} onClick={() => void act({ type: "rematch" })}><RefreshCw size={17} />Ďalšia partia</button> : <p className="muted">Ďalšiu partiu môže otvoriť hostiteľ.</p>}</section>}
      <section className="scoreboard" aria-label="Prehľad hráčov">{room.players.map(player => <button className={`score-player ${current?.id === player.id && room.phase === "playing" ? "current" : ""} ${player.id === room.you ? "self" : ""}`} key={player.id} onClick={() => player.characterId && openDetail(player.characterId, "character", player.id)}>{player.characterId && <img src={art(cards[player.characterId])} alt={cards[player.characterId].name} />}<div className="score-info"><strong>{player.name}{player.bot && <Bot size={14} aria-label="Počítačový súper" />}{player.id === room.you && <small>TY</small>}</strong><div className="score-track"><span style={{ width: `${Math.min(100, player.stats.hearts / room.options.goal * 100)}%` }} /></div><span className="muted">{player.handCount} v ruke · {player.stats.usedSlots}/{player.stats.slots} miest</span></div><span className="score-hearts"><Heart size={15} fill="currentColor" />{player.stats.hearts}</span></button>)}</section>
      {capacitiesBlocked && <div className="capacity-warning" role="status"><CircleHelp size={18} /><span>{overflow ? "Tvoja zostava prekračuje kapacitu. Odhoď vyloženú kartu alebo vo svojom ťahu vylož pasívku, ktorá pokryje deficit." : `Čakáme na úpravu kapacity: ${room.players.filter(p => room.capacityPlayers?.includes(p.id)).map(p => p.name).join(", ")}.`}{room.pendingDraw ? " Potom bude pokračovať doberanie a partia." : " Potom bude partia pokračovať."}</span></div>}
      <div className="game-layout"><div className="table-main">{room.auction ? <section className="auction-banner surface"><div className="auction-target"><button onClick={() => openDetail(room.auction!.targetId)}><img src={art(cards[room.auction.targetId])} alt={cards[room.auction.targetId].name} /></button><div><p className="eyebrow"><Swords size={14} /> SUMMON PREBIEHA</p><h2>{cards[room.auction.targetId].name}</h2><p><strong>{room.players.find(p => p.id === room.auction!.leaderId)?.name}</strong> vedie s <b className="gold">{room.auction.bids[room.auction.leaderId].power} tames</b>.</p><div className="auction-status">{room.players.map(p => <span key={p.id} className={p.id === room.auction!.leaderId ? "leader" : room.auction!.passes.includes(p.id) ? "passed" : ""}>{p.name}{p.id === room.auction!.leaderId ? " · vedie" : room.auction!.passes.includes(p.id) ? " · pas" : " · rozmýšľa"}</span>)}</div></div></div>{timerDisplay}<div className="auction-buttons">{myAuctionLeader ? <span className="leading-notice"><Crown size={19} />Tvoja ponuka vedie</span> : <><button className="button primary" disabled={busy || capacitiesBlocked || alreadyPassed || expired || !me?.stats.freeSlots} onClick={() => startComposer("bid")}><Plus size={17} />Prihodiť</button><button className="button secondary" disabled={busy || capacitiesBlocked || alreadyPassed || expired} onClick={() => void act({ type: "pass" })}>{alreadyPassed ? "Pas potvrdený" : "Pas"}</button></>}<p className="small-text muted">Každé nové prihodenie otvorí reakcie všetkým hráčom znova.</p></div></section> : room.phase === "playing" && <div className={`turn-banner ${myTurn ? "your-turn" : ""}`}><span className="turn-symbol"><Swords size={22} /></span><div><strong>{myTurn ? "Si na ťahu." : `Na ťahu je ${current?.name}.`}</strong><p>{myTurn ? "Rozvíjaj zostavu alebo začni summon kartou z ruky." : current?.bot ? "Počítač premýšľa a zahrá automaticky. Pri summone môžeš prihodiť aj ty." : "Sleduj súperovu stratégiu. Pri summone môžeš prihodiť aj ty."}</p></div>{myTurn && <button className="button secondary" disabled={!canAct} onClick={() => { setDiscards([]); setEndSpecial("regular"); setEndTarget(""); setShowEnd(true); }}>Ukončiť ťah<ArrowRight size={16} /></button>}</div>}
      {me && <section className="surface own-board"><div className="section-heading"><div><p className="eyebrow">TVOJA ZOSTAVA</p><h2><button className="character-name-button" onClick={() => me.characterId && openDetail(me.characterId, "character", me.id)}>{me.characterId ? cards[me.characterId].name : me.name}<CircleHelp size={15} /></button></h2></div><StatLine stats={me.stats} /></div><div className="board-zone"><span className="zone-label">HÁREM <b>{me.harem.length}/{me.stats.slots}</b></span>{me.harem.length ? <div className="card-row">{me.harem.map(permanent => <CardTile key={permanent.id} id={permanent.id} dead={permanent.dead} small onClick={() => openDetail(permanent.id, "permanent", me.id)} />)}</div> : <div className="empty-zone"><Heart size={22} /><p>Prvé srdcia ešte len čakajú.<span>Začni summon dievčaťa alebo podpory z ruky.</span></p></div>}</div><div className="board-zone support-zone"><span className="zone-label">SCHOPNOSTI · CHARGE · ROZŠÍRENIA</span>{me.table.length ? <div className="card-row">{me.table.map(permanent => <CardTile key={permanent.id} id={permanent.id} small onClick={() => openDetail(permanent.id, "permanent", me.id)} footer={cards[permanent.id].type === "charge" ? (permanent.readyAt || 0) <= me.turns ? <span className="ready-charge">Nabité · pripravené</span> : "Nabíja sa do ďalšieho ťahu" : typeLabels[cards[permanent.id].type]} />)}</div> : <p className="empty-support">Tu budú tvoje vyložené karty. Hviezdy určujú ich spoločnú kapacitu.</p>}</div></section>}
      {me && <section className="surface hand-section"><div className="section-heading"><div><p className="eyebrow">LEN PRE TVOJE OČI</p><h2>Tvoja ruka <span>{me.hand.length}/{me.stats.hand}</span></h2></div><span className="small-text muted">Otvor kartu a vyber akciu</span></div>{me.endPayment && <p className="reserved-payment"><Shield size={16} />Karta súpera je rezervovaná na koniec tvojho ťahu.</p>}{me.hand.length ? <div className="card-row hand-row">{me.hand.map(id => <CardTile key={id} id={id} onClick={() => openDetail(id, "hand", me.id)} footer={cards[id].cost.tames ? `${cards[id].cost.tames} tames · ${typeLabels[cards[id].type]}` : cards[id].cost.stars ? `${cards[id].cost.stars} ★ · ${typeLabels[cards[id].type]}` : typeLabels[cards[id].type]} />)}</div> : <div className="empty-zone"><Hand size={24} /><p>Ruka je prázdna.<span>Karty sa dobierajú na začiatku tvojho ťahu.</span></p></div>}</section>}
      <section className="opponent-boards"><h2 className="minor-heading">Na druhej strane stola</h2>{room.players.filter(p => p.id !== room.you).map(player => <details className="surface opponent-board" key={player.id}><summary><span><strong>{player.name}</strong><small>{player.characterId && cards[player.characterId].name}</small></span><StatLine stats={player.stats} compact /><ChevronDown size={17} /></summary><div className="opponent-content"><div className="card-row">{[...player.harem, ...player.table].map(permanent => <CardTile key={permanent.id} id={permanent.id} small dead={permanent.dead} onClick={() => openDetail(permanent.id, "permanent", player.id)} />)}{!player.harem.length && !player.table.length && <p className="muted">Zatiaľ nemá vyložené karty.</p>}</div><div className="hidden-hand"><Layers3 size={18} />{player.handCount} skrytých kariet v ruke</div></div></details>)}</section></div><aside className="game-sidebar"><section className="surface event-log"><div className="section-heading"><h2>Priebeh hry</h2><span className="live-dot" /></div><ol>{room.logs.slice(-18).reverse().map(item => <li key={item.id}><span>{String(item.id).padStart(2, "0")}</span><p>{item.text}</p></li>)}</ol></section><div className="table-note"><CircleHelp size={17} /><p>Hviezdy sa nemíňajú. Vyložené karty ich obsadia, až kým ich nepoužiješ alebo nevymeníš.</p></div><button className="text-button muted" onClick={() => setShowRules(true)}><BookOpen size={16} />Otvoriť pravidlá</button></aside></div>
    </main>}
    {showCatalog && <Modal title="Kolekcia kariet" onClose={closeCatalog} wide><div className="catalog-toolbar"><div className="search-field"><Search size={18} /><input aria-label="Hľadať kartu" value={query} onChange={e => setQuery(e.target.value)} placeholder="Meno, typ alebo schopnosť…" /></div><select aria-label="Druh karty" value={filter} onChange={e => setFilter(e.target.value)}><option value="all">Všetky druhy</option>{Object.entries(typeLabels).map(([key, label]) => <option value={key} key={key}>{label}</option>)}</select></div><p className="muted small-text">{catalogueCards.length} kariet · Každá fyzická kópia má v balíčku vlastné miesto.</p><div className="catalog-grid">{catalogueCards.map(card => <CardTile id={card.id} key={card.id} onClick={() => openDetail(card.id)} />)}</div>{!catalogueCards.length && <div className="empty-zone"><Search size={25} /><p>Takú kartu sme nenašli.<span>Skús kratší názov alebo iný filter.</span></p></div>}</Modal>}
    {showCharacters && room && <Modal title="Vyber si svoju postavu" onClose={closeCharacters} wide><p className="muted">Pozri si schopnosti a vyber postavu pre svoju stratégiu.</p><div className="catalog-grid">{characters.map(card => <CardTile key={card.id} id={card.id} selected={me?.characterId === card.id} onClick={() => openDetail(card.id)} action={<button className={`button ${me?.characterId === card.id ? "primary" : "secondary"} full small-button`} disabled={busy} onClick={async () => { if (await act({ type: "choose", cardId: card.id })) setShowCharacters(false); }}>{me?.characterId === card.id ? "Vybraná" : "Vybrať"}</button>} />)}</div></Modal>}
    {detailCard && detail && <Modal title={detailCard.name} onClose={closeDetail}><div className="card-detail"><img className="detail-image" src={art(detailCard)} alt={detailCard.name} /><div className="detail-copy"><span className={`type-badge type-${detailCard.type}`}>{typeLabels[detailCard.type]}{detailCard.subtype ? ` · ${detailCard.subtype}` : ""}</span><p className="effect-text">{rulesText(detailCard.effectText)}</p><div className="detail-stats">{Object.entries(detailCard.base).filter(([, n]) => n).map(([key, value]) => <span key={key}>{({ hearts: "♥", stars: "★", tames: "✦", hand: "♠", slots: "⬡" } as Record<string, string>)[key]} {value}</span>)}{!!detailCard.cost.stars && <span>Kapacita {detailCard.cost.stars} ★</span>}{!!detailCard.cost.tames && <span>Summon {detailCard.cost.tames} ✦</span>}</div>{detail.place === "hand" && room?.phase === "playing" && <div className="detail-actions">{["girl", "support"].includes(detailCard.type) && <button className="button primary full" disabled={!canAct} onClick={() => startComposer(detailCard.id)}><Swords size={17} />Začať summon</button>}{["ability", "charge", "harem"].includes(detailCard.type) && <><p className="small-text muted">{detailCard.type === "charge" ? "Charge sa nabije na začiatku tvojho ďalšieho ťahu." : "Karta obsadí hviezdy. Jej vlastné bonusy sa započítajú už pri vyložení."}</p>{me && [...me.table, ...me.harem].length > 0 && <details className="replacement-picker"><summary>Vymeniť vyložené karty <span>voliteľné</span></summary>{[...me.table, ...me.harem].map(p => <label key={p.id}><input type="checkbox" checked={replace.includes(p.id)} onChange={() => setReplace(toggleIn(replace, p.id))} />{cards[p.id].name}<small>{cards[p.id].cost.stars || 0} ★</small></label>)}</details>}{deploymentStats && <div className={`deployment-preview ${deploymentFits ? "" : "invalid"}`}><strong>Po vyložení vrátane pasívok</strong><p>★ Hviezdy: {me?.stats.usedStars}/{me?.stats.stars} → <b>{deploymentStats.usedStars}/{deploymentStats.stars}</b></p><p>⬡ Miesta: {me?.stats.usedSlots}/{me?.stats.slots} → <b>{deploymentStats.usedSlots}/{deploymentStats.slots}</b></p><p>♥ {deploymentStats.hearts} sŕdc · ♠ limit ruky {deploymentStats.hand} · ✦ {deploymentStats.tames} tames</p>{!deploymentFits && <p>Kapacita nestačí. Vyber karty na výmenu.</p>}</div>}{me && me.hand.length === 1 && !me.endPayment && (deploymentStats?.hearts || 0) < room.options.goal && <p className="reserve-warning">Toto je posledná karta v ruke. Na ukončenie ťahu si musíš nechať jednu kartu alebo mať rezervovanú kartu súpera.</p>}<button className="button primary full" disabled={!canDeploy || !deploymentFits} onClick={async () => { if (await act({ type: "deploy", cardId: detailCard.id, replace })) setDetail(null); }}><Plus size={17} />Vyložiť kartu</button></>}{detailCard.type === "tame" && <p className="small-text muted">Tame kartu pridáš do ponuky pri summone alebo prihodení.</p>}{!myTurn && <p className="small-text muted">Vykladať môžeš vo svojom ťahu.</p>}{room?.auction && <p className="small-text muted">Najprv dokončite prebiehajúci summon.</p>}</div>}{selectedPermanent && me && <div className="detail-actions">{detailCard.type === "girl" && mySpecials.filter(source => !me.usedActions.includes(source.id) && (source.special === "killRevive" || source.special === (selectedPermanent.dead ? "revive" : "kill"))).map(source => <button key={`${source.id}-${source.special}`} className="button secondary full" disabled={!canAct} onClick={async () => { if (await act({ type: "special", sourceId: source.id, targetId: detailCard.id, mode: selectedPermanent.dead ? "revive" : "kill" })) setDetail(null); }}><Sparkles size={17} />{selectedPermanent.dead ? "Oživiť" : "Obetovať"} · {cards[source.id].name}</button>)}<button className="button danger-outline full" disabled={!canClean} onClick={async () => { if (await act({ type: "discardPermanent", cards: [detailCard.id] })) setDetail(null); }}>Odhodiť zo zostavy</button></div>}</div></div></Modal>}
    {composer && room && me && targetCard && <Modal title={composer === "bid" ? "Prihoď do summonu" : "Priprav svoj summon"} onClose={closeComposer} wide>{composer === "bid" && timerDisplay}<div className="bid-intro"><img src={art(targetCard)} alt={targetCard.name} /><div><p className="eyebrow">BOJUJEŠ O KARTU</p><h3>{targetCard.name}</h3><p>Vyber Tame karty z ruky a nabité Charge zo stola. Bonusy tvojej zostavy sa pripočítajú automaticky.</p></div><div className={`bid-number ${preview >= threshold ? "enough" : ""}`}><span>TVOJA PONUKA</span><b>{preview}<PawPrint size={25} /></b><small>potrebuješ aspoň {threshold}</small></div></div>{composer !== "bid" && !me.endPayment && mySpecials.some(s => s.special === "endWithOpponentCard") && <div className="reserve-picker"><label className="field-label" htmlFor="reserve-opponent">Schopnosť: rezervovať súperovu kartu na koniec ťahu</label><select id="reserve-opponent" value={reserveOpponent} onChange={e => setReserveOpponent(e.target.value)}><option value="">Nechať si vlastnú kartu na odhodenie</option>{room.players.filter(p => p.id !== me.id && p.handCount > 0).map(p => <option key={p.id} value={p.id}>{p.name} · {p.handCount} kariet v ruke</option>)}</select><p className="small-text muted">Pri začatí summonu sa náhodná karta súpera rezervuje. Súper ju už nemôže zahrať a odhodí sa na konci tvojho ťahu.</p></div>}<div className="bid-candidates">{candidateIds.map(id => <CardTile key={id} id={id} selected={bidCards.includes(id)} onClick={() => setBidCards(toggleIn(bidCards, id))} footer={cards[id].type === "charge" ? "Nabitá Charge" : "Tame z ruky"} action={<button className={`button ${bidCards.includes(id) ? "primary" : "secondary"} full small-button`} onClick={() => setBidCards(toggleIn(bidCards, id))}>{bidCards.includes(id) ? <Check size={15} /> : <Plus size={15} />}{bidCards.includes(id) ? "V ponuke" : "Pridať"}</button>} />)}</div>{!candidateIds.length && <p className="muted">Nemáš Tame ani nabitú Charge. Ponuku môže pokryť pasívna sila a bonusy.</p>}<div className="modal-footer"><p className="small-text muted">Použité karty sa po summone odhodia. Karty sa nedoberajú počas súboja.</p><button className="button primary" disabled={busy || capacitiesBlocked || preview < threshold || (composer === "bid" && (myAuctionLeader || alreadyPassed || expired))} onClick={submitBid}><Swords size={17} />{composer === "bid" ? `Prihodiť ${preview} tames` : `Summon za ${preview} tames`}</button></div></Modal>}
    {showEnd && me && room && <Modal title="Ukončiť tvoj ťah" onClose={closeEnd} wide>{me.endPayment ? <p className="reserved-payment"><Shield size={17} />Karta súpera je rezervovaná na koniec ťahu. Nemusíš odhodiť vlastnú kartu, ak neprekračuješ limit ruky.</p> : <p className="muted">Vyber aspoň jednu kartu na odhodenie. Ak máš karty nad limit ruky, odhoď ich tiež.</p>}<div className="end-summary"><span>Ruka po odhodení: <b>{me.hand.length - discards.length}/{me.stats.hand}</b></span><span>Vybrané: <b>{discards.length}</b></span></div><div className="bid-candidates">{me.hand.map(id => <CardTile key={id} id={id} selected={discards.includes(id)} onClick={() => setDiscards(toggleIn(discards, id))} action={<button className={`button ${discards.includes(id) ? "primary" : "secondary"} full small-button`} onClick={() => setDiscards(toggleIn(discards, id))}>{discards.includes(id) ? <Check size={15} /> : <Plus size={15} />}{discards.includes(id) ? "Odhodiť" : "Vybrať"}</button>} />)}</div>{!me.endPayment && mySpecials.some(x => x.special === "endWithDeadGirl") && <div className="end-special"><label className="field-label" htmlFor="end-method">Spôsob ukončenia</label><select id="end-method" value={endSpecial} onChange={e => { setEndSpecial(e.target.value); setEndTarget(""); }}><option value="regular">Odhodiť vlastnú kartu z ruky</option><option value="dead">Schopnosť: odhodiť mŕtve dievča</option></select>{endSpecial === "dead" && <select aria-label="Vyber mŕtve dievča" value={endTarget} onChange={e => setEndTarget(e.target.value)}><option value="">Vyber mŕtve dievča</option>{room.players.flatMap(p => p.harem.filter(c => c.dead && cards[c.id].type === "girl").map(c => <option key={c.id} value={c.id}>{cards[c.id].name} · {p.name}</option>))}</select>}</div>}<div className="modal-footer"><button className="button secondary" onClick={closeEnd}>Späť do hry</button><button className="button primary" disabled={busy || capacitiesBlocked || (!me.endPayment && (endSpecial === "regular" ? !discards.length : !endTarget)) || me.hand.length - discards.length > me.stats.hand} onClick={endTurn}>Odhodiť a ukončiť<ArrowRight size={17} /></button></div></Modal>}
    {showRules && <Modal title="Ako sa hrá Battle Harem" onClose={closeRules} wide><div className="rules-layout"><div className="rules-intro"><Heart size={35} /><h3>Získaj srdcia.<br />Poskladaj víťaznú zostavu.</h3><p>Hra pre 2 až 8 hráčov. Vyhrávaš okamžite, keď dosiahneš zvolený cieľ 25, 36 alebo 50 sŕdc.</p><div className="rules-symbols"><span>♥ Srdcia <small>víťazné body</small></span><span>★ Hviezdy <small>kapacita vyložených kariet</small></span><span>✦ Tames <small>sila v súboji o kartu</small></span><span>♠ Ruka <small>do koľkých kariet doberáš</small></span><span>⬡ Miesta <small>kapacita háremu</small></span></div></div><div className="rules-steps"><section><span>01</span><div><h4>Príprava a tvoj ťah</h4><p>Hrať môžeš aj sám proti 1 až 7 počítačom alebo ich kombinovať s kamarátmi. Hostiteľ ich pridáva a odoberá pred začiatkom partie. Počítače si vyberú postavu a potvrdia pripravenosť automaticky; rozhodujú podľa vlastnej ruky a verejnej zostavy.</p><p>Vyberte postavy alebo ich nechajte vyžrebovať. Všetky ostatné karty tvoria spoločný zamiešaný balíček. Na začiatku vlastného ťahu si doplníš ruku do aktuálneho limitu.</p></div></section><section><span>02</span><div><h4>Rozvíjaj svoju zostavu</h4><p>Schopnosti, Charge a rozšírenia háremu vykladáš vo svojom ťahu. Obsadzujú hviezdnu kapacitu. Vyložené karty môžeš vymeniť alebo odhodiť. Charge sa nabije na začiatku tvojho ďalšieho ťahu a po použití sa odhodí.</p></div></section><section><span>03</span><div><h4>Summon a prihadzovanie</h4><p>Vyber Girl alebo Support z ruky a pokry jej cenu svojimi tames. Ostatní hráči môžu ponúknuť vyšší súčet alebo stlačiť Pas. Tvoje predchádzajúce prihodenie zostáva započítané. Nové prihodenie znovu otvorí reakcie ostatným a obnoví čas na reakciu. Hostiteľ môže nastaviť 30 sekúnd až 2 minúty alebo hru bez limitu. Predvolene je to 1 minúta; po vypršaní času ostatní automaticky pasujú.</p><p>Keď všetci okrem lídra pasujú, líder získa kartu. Použité Tame aj Charge idú do odhadzovacieho balíčka. Počas summonu sa nedoberá.</p></div></section><section><span>04</span><div><h4>Koniec ťahu a bonusy</h4><p>Na konci ťahu odhoď aspoň jednu kartu z ruky; niektoré schopnosti umožnia náhradu. Umaru Yone a Creepy Turn rezervujú náhodnú kartu súpera už pri začatí summonu. Girl aj Support zaberajú miesto, Support sa však nepočíta ako dievča. Bonusy a srdcia sa počítajú automaticky.</p><p>Mŕtve dievča stráca vlastné srdcia a pasíva, ale zostáva v háreme a počíta sa pre ostatné schopnosti podľa typu. Aktivované schopnosti obetovania či oživenia možno použiť raz za vlastný ťah.</p></div></section><div className="rules-cap"><strong>Limity podľa cieľa</strong><p>25 ♥: ruka max. 8, všeobecné pasívne tames max. 6.<br />36 ♥: ruka max. 9, pasívne tames max. 7.<br />50 ♥: ruka max. 10, pasívne tames max. 8.</p><p>Bonusy proti konkrétnemu typu sa do limitu tames nepočítajú. Hráč bez dievčat má +1 limit ruky za každé dievča vo všetkých háremoch, najviac po príslušný strop.</p><details className="digital-rules"><summary>Doplnenia digitálnej verzie</summary><p>Po vyčerpaní balíčka sa zamiešajú odhodené karty. Pri vlastnom výbere sa môžu postavy opakovať. Pred summonom musíš mať voľné miesto. Pri súčasnej výhre rozhoduje poradie od hráča na ťahu.</p><p>Prekročenú kapacitu opraví jej majiteľ odhodením vyložených kariet alebo vo vlastnom ťahu vyložením karty, ktorá deficit pokryje; dovtedy ostatné akcie a doberanie čakajú. Ponuka najprv použije Charge a potom Tame v poradí výberu. Bežné hranie ponecháva kartu na koniec ťahu, ak nemáš rezervovanú kartu súpera.</p><p>Power Play predbežne zvyšuje limit ruky za vlastné nabíjajúce sa Charge. Akujima odkazuje na chýbajúcu Riza Hawkeye, preto tento bonus zatiaľ neúčinkuje. Tieto doplnenia môžeme upraviť podľa autora.</p><p>Odpojený hráč sa vráti na rovnakom prehliadači. Miestnosť vydrží sedem dní od poslednej akcie; pri zapnutom časovači aj odpojený hráč v summone automaticky pasuje. Časovač neukončuje bežný ťah. Počítače hrajú, kým má aspoň jeden hráč otvorenú a pripojenú hru. Po návrate pokračujú. Aj hra proti počítaču potrebuje internet.</p></details></div></div></div></Modal>}
  </div>;
}
